response:
[
  {
    "id": 1,
    "source": "<font color=\"#00FFFF\">Das macht mich nervös.</font>\n<font color=\"#FFFFFF\">* Das Handy vibriert. *</font>",
    "text": "<font color=\"#00FFFF\">این منو عصبی می‌کنه</font>\n<font color=\"#FFFFFF\">* صدای لرزش گوشی *</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FF00\">Guten Morgen, Jonas.</font>\n<font color=\"#00FF00\">Nee, nee. Überhaupt kein Problem.</font>",
    "text": "<font color=\"#00FF00\">صبح بخیر یوناس</font>\n<font color=\"#00FF00\">نه نه، اصلاً مشکلی نیست</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#00FF00\">Ja. Nee, gerne. Ja?</font>",
    "text": "<font color=\"#00FF00\">آره، نه، خواهش می‌کنم، آره؟</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#00FF00\">Ja. Gerne, ja.</font>\n<font color=\"#00FFFF\">Ähm...</font>",
    "text": "<font color=\"#00FF00\">آره، حتماً، آره</font>\n<font color=\"#00FFFF\">ام...</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#00FFFF\">Guck mal.</font>",
    "text": "<font color=\"#00FFFF\">یه نگاه بنداز</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#00FF00\">Hey, hey. Alles gut.</font>",
    "text": "<font color=\"#00FF00\">هی هی، همه‌چی مرتبه</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#00FF00\">Ja,</font>\n<font color=\"#00FF00\">das habe ich so auch verstanden.</font>",
    "text": "<font color=\"#00FF00\">آره</font>\n<font color=\"#00FF00\">منم همین‌طوری متوجه شدم</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#00FF00\">Mhm.</font>",
    "text": "<font color=\"#00FF00\">هوم</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#00FF00\">Was?</font>\n<font color=\"#00FFFF\">Denk an unsere Abmachung.</font>",
    "text": "<font color=\"#00FF00\">چی؟</font>\n<font color=\"#00FFFF\">یادت باشه چی قرار گذاشتیم</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#00FFFF\">Wir sind eine moderne Familie.</font>",
    "text": "<font color=\"#00FFFF\">ما یه خانواده مدرنیم</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#00FF00\">Definitiv, aber die Hürde</font>\n<font color=\"#00FF00\">für eine fristlose Kündigung</font>",
    "text": "<font color=\"#00FF00\">قطعاً، ولی اون مانع</font>\n<font color=\"#00FF00\">برای اخراج فوری</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#00FF00\">werden wir nicht erreichen.</font>",
    "text": "<font color=\"#00FF00\">رو نمی‌تونیم رد کنیم</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#00FF00\">Theo,</font>\n<font color=\"#00FF00\">ich kann von zu Hause arbeiten.</font>",
    "text": "<font color=\"#00FF00\">تئو</font>\n<font color=\"#00FF00\">من می‌تونم از خونه کار کنم</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FFFF\">Auf keinen Fall.</font>",
    "text": "<font color=\"#00FFFF\">اصلاً حرفشم نزن</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#00FF00\">Das können wir machen, aber ich</font>\n<font color=\"#00FF00\">weiß nicht, ob das gut ankommt.</font>",
    "text": "<font color=\"#00FF00\">می‌تونیم این کارو بکنیم، ولی</font>\n<font color=\"#00FF00\">نمی‌دونم بازخوردش خوب باشه یا نه</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FFFF\">Vertrau mir.</font>\n<font color=\"#00FF00\">Genau.</font>",
    "text": "<font color=\"#00FFFF\">به من اعتماد کن</font>\n<font color=\"#00FF00\">دقیقاً</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FF00\">Das können wir gerne so machen.</font>\n<font color=\"#00FFFF\">Okay.</font>",
    "text": "<font color=\"#00FF00\">خیلی هم عالی، همین کارو می‌کنیم</font>\n<font color=\"#00FFFF\">باشه</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FF00\">Alles wird gut. Tschüss.</font>\n<font color=\"#00FFFF\">Komm.</font>",
    "text": "<font color=\"#00FF00\">همه‌چی درست می‌شه، خداحافظ</font>\n<font color=\"#00FFFF\">بیا</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#00FFFF\">Mama kommt bald wieder, okay?</font>\n<font color=\"#00FFFF\">Mama kommt bald zurück.</font>",
    "text": "<font color=\"#00FFFF\">مامان زود برمی‌گرده، باشه؟</font>\n<font color=\"#00FFFF\">مامان زود میاد پیشت</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">Schülerpraktika sind doch dafür da,</font>",
    "text": "<font color=\"#FFFFFF\">کارآموزی دانش‌آموزی واسه اینه که</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">um einen ersten Einblick</font>\n<font color=\"#FFFFFF\">in die Arbeit zu bekommen.</font>",
    "text": "<font color=\"#FFFFFF\">یه دید کلی از کار</font>\n<font color=\"#FFFFFF\">پیدا کنن</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFF00\">Genau dafür sind wir hier.</font>\n<font color=\"#FFFF00\">Was, Rocci?</font>",
    "text": "<font color=\"#FFFF00\">دقیقاً واسه همین اینجاییم</font>\n<font color=\"#FFFF00\">چیه روکی؟</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Rocco hatte bereits</font>\n<font color=\"#FFFFFF\">den Ferienjob bei uns.</font>",
    "text": "<font color=\"#FFFFFF\">روکو قبلاً</font>\n<font color=\"#FFFFFF\">کار تابستونی پیش ما داشت</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Vorkenntnisse</font>\n<font color=\"#FFFF00\">können ja auch nützlich sein, was?</font>",
    "text": "<font color=\"#FFFF00\">تجربه قبلی</font>\n<font color=\"#FFFF00\">می‌تونه خیلی مفید باشه، مگه نه؟</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">Der Junge wurde gekündigt.</font>",
    "text": "<font color=\"#FFFFFF\">اون پسر اخراج شد</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Weil er immer vergessen hat,</font>\n<font color=\"#FFFFFF\">die Kühltruhe zuzumachen.</font>",
    "text": "<font color=\"#FFFFFF\">چون همیشه یادش می‌رفت</font>\n<font color=\"#FFFFFF\">درِ فریزر رو ببنده</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Wissen Sie,</font>\n<font color=\"#FFFF00\">jeder Mensch macht mal Fehler.</font>",
    "text": "<font color=\"#FFFF00\">می‌دونید،</font>\n<font color=\"#FFFF00\">هر آدمی ممکنه اشتباه کنه</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">Auch Sie und ich,</font>\n<font color=\"#FFFF00\">wenn wir ehrlich sind.</font>",
    "text": "<font color=\"#FFFF00\">هم من و هم شما،</font>\n<font color=\"#FFFF00\">اگه بخوایم صادق باشیم</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">Nobody is perfect.</font>",
    "text": "<font color=\"#FFFF00\">هیچ‌کس کامل نیست</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">Aber wenn einer</font>\n<font color=\"#FFFF00\">eine zweite Chance verdient hat,</font>",
    "text": "<font color=\"#FFFF00\">ولی اگه کسی باشه که</font>\n<font color=\"#FFFF00\">لایق یه فرصت دوباره باشه،</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFF00\">dann dieser junge Mann hier.</font>",
    "text": "<font color=\"#FFFF00\">اون همین جوون‌مرد اینجاست</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">(leise) Lächeln, Rocci.</font>",
    "text": "<font color=\"#FFFF00\">(آروم) بخند، روکی</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Ja, gut. Ich quatsche</font>\n<font color=\"#FFFFFF\">noch mal mit meinem Chef.</font>",
    "text": "<font color=\"#FFFFFF\">آره، خب. من دوباره</font>\n<font color=\"#FFFFFF\">با رئیسم صحبت می‌کنم</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Und ... dann melden wir</font>\n<font color=\"#FFFFFF\">uns bei Ihnen irgendwann.</font>",
    "text": "<font color=\"#FFFFFF\">و... بعدش یه وقتی</font>\n<font color=\"#FFFFFF\">بهتون خبر می‌دیم</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Vielleicht.</font>",
    "text": "<font color=\"#FFFFFF\">شاید</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Mehr kann ich nicht für Sie tun.</font>",
    "text": "<font color=\"#FFFFFF\">بیشتر از این کاری از دستم برنمیاد</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">Wenn du was ganz doll willst,</font>\n<font color=\"#FFFF00\">musst du auch was dafür tun.</font>",
    "text": "<font color=\"#FFFF00\">اگه چیزی رو خیلی می‌خوای،</font>\n<font color=\"#FFFF00\">باید براش مایه بذاری</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Blöd aus der Wäsche gucken</font>\n<font color=\"#FFFF00\">und das Maul nicht aufkriegen.</font>",
    "text": "<font color=\"#FFFF00\">نه اینکه فقط احمقانه نگاه کنی</font>\n<font color=\"#FFFF00\">و دهنت رو هم باز نکنی</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Ich will da nicht arbeiten.</font>\n<font color=\"#FFFF00\">Aber darum geht es ja gar nicht.</font>",
    "text": "<font color=\"#FFFFFF\">من نمی‌خوام اونجا کار کنم</font>\n<font color=\"#FFFF00\">ولی اصلاً بحث این نیست</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Ich meine, irgendwo musst du</font>\n<font color=\"#FFFF00\">dein Praktikum ja machen.</font>",
    "text": "<font color=\"#FFFF00\">منظورم اینه که بالاخره باید</font>\n<font color=\"#FFFF00\">کارآموزیت رو یه جایی بگذرونی</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">Wie sieht das aus,</font>\n<font color=\"#FFFF00\">wenn du als Einziger in der Klasse</font>",
    "text": "<font color=\"#FFFF00\">چه وجهه‌ای داره،</font>\n<font color=\"#FFFF00\">اگه تنها کسی باشی تو کلاس که</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">keine Stelle findest?</font>",
    "text": "<font color=\"#FFFF00\">جایی رو پیدا نکردی؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">Papa? Wo ist unser Fahrrad?</font>\n<font color=\"#FFFF00\">Hm?</font>",
    "text": "<font color=\"#FFFFFF\">بابا؟ دوچرخه‌مون کجاست؟</font>\n<font color=\"#FFFF00\">ها؟</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">Rocco...</font>",
    "text": "<font color=\"#FFFF00\">روکو...</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Wo hast du das dran angeschlossen?</font>",
    "text": "<font color=\"#FFFF00\">کجا قفلش کردی؟</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Na da, wo das Schloss ist.</font>",
    "text": "<font color=\"#FFFFFF\">خب همون‌جایی که قفل هست دیگه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFF00\">Ich meine am Rad, du Pflaume.</font>",
    "text": "<font color=\"#FFFF00\">منظورم روی دوچرخه است، احمق جان</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFF00\">Wo hast du das Schloss</font>\n<font color=\"#FFFF00\">am Fahrrad festgemacht?</font>",
    "text": "<font color=\"#FFFF00\">قفل رو کجای دوچرخه</font>\n<font color=\"#FFFF00\">بستی؟</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Sag bitte nicht</font>\n<font color=\"#FFFF00\">\"an der Sattelstange\".</font>",
    "text": "<font color=\"#FFFF00\">توروخدا نگو</font>\n<font color=\"#FFFF00\">«به میله‌ی زین»</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Das kommt davon,</font>\n<font color=\"#FFFF00\">dass du den verhätschelst.</font>",
    "text": "<font color=\"#FFFF00\">اینا همه‌ش نتیجه‌ی</font>\n<font color=\"#FFFF00\">لوس کردنشه</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFF00\">Um nichts muss er sich kümmern,</font>\n<font color=\"#FFFF00\">weil du alles regelst.</font>",
    "text": "<font color=\"#FFFF00\">مجبور نیست به هیچ‌چی فکر کنه،</font>\n<font color=\"#FFFF00\">چون تو همه‌چیو ردیف می‌کنی</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">* Auf Vietnamesisch *</font>",
    "text": "<font color=\"#FFFFFF\">* به زبان ویتنامی *</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">Der weiß nicht,</font>\n<font color=\"#FFFF00\">was Verantwortung ist.</font>",
    "text": "<font color=\"#FFFF00\">اصلاً نمی‌دونه</font>\n<font color=\"#FFFF00\">مسئولیت یعنی چی</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">Er muss das lernen,</font>\n<font color=\"#FFFF00\">sonst renne ich noch als Rentner</font>",
    "text": "<font color=\"#FFFF00\">باید یاد بگیره،</font>\n<font color=\"#FFFF00\">وگرنه وقتی بازنشسته هم بشم باید</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">mit zu den Bewerbungsgesprächen.</font>",
    "text": "<font color=\"#FFFF00\">باهاش برم مصاحبه‌های کاری</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Wieso macht Rocci</font>\n<font color=\"#FFFFFF\">sein Praktikum nicht hier?</font>",
    "text": "<font color=\"#FFFFFF\">چرا روکی</font>\n<font color=\"#FFFFFF\">کارآموزیشو اینجا نمی‌گذرونه؟</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Was soll der als Junge</font>\n<font color=\"#FFFF00\">im Nadelstudio?</font>",
    "text": "<font color=\"#FFFF00\">یه پسر تو</font>\n<font color=\"#FFFF00\">استودیوی سوزن‌دوزی چیکار می‌خواد بکنه؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FF00FF\">Ich habe ihn</font>\n<font color=\"#FF00FF\">schon genug um mich rum.</font>",
    "text": "<font color=\"#FF00FF\">همین‌جوری هم</font>\n<font color=\"#FF00FF\">دور و برم زیادی می‌پلکه</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Ich würde mich bei Tecla bewerben.</font>",
    "text": "<font color=\"#FFFFFF\">من بودم واسه «تکلا» رزومه می‌فرستادم</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFFFF\">Macht sich gut aufm CV.</font>",
    "text": "<font color=\"#FFFFFF\">تو رزومه خیلی خوب جلوه می‌کنه</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Aber ohne Connection</font>\n<font color=\"#FFFFFF\">wird das nichts.</font>",
    "text": "<font color=\"#FFFFFF\">ولی بدون پارتی‌بازی</font>\n<font color=\"#FFFFFF\">هیچی به هیچی</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFFFF\">Da will jeder arbeiten.</font>",
    "text": "<font color=\"#FFFFFF\">همه می‌خوان اونجا کار کنن</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">* Auf Vietnamesisch *</font>",
    "text": "<font color=\"#FFFFFF\">* به زبان ویتنامی *</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Da muss er sich drum kümmern.</font>\n<font color=\"#FFFFFF\">Und lernt Verantwortung.</font>",
    "text": "<font color=\"#FFFFFF\">باید خودش پیگیرش باشه</font>\n<font color=\"#FFFFFF\">تا مسئولیت‌پذیری یاد بگیره</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Wie wäre es mit einem Hamster?</font>",
    "text": "<font color=\"#FFFFFF\">نظرت چیه یه همستر براش بگیریم؟</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Die gehen nicht so schnell kaputt</font>\n<font color=\"#FFFFFF\">und sind billig.</font>",
    "text": "<font color=\"#FFFFFF\">زود هم نمی‌میرن</font>\n<font color=\"#FFFFFF\">و ارزون هم هستن</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">* Frida schreit. *</font>\n<font color=\"#00FF00\">Hat sie getrunken?</font>",
    "text": "<font color=\"#FFFFFF\">* فریدا گریه می‌کند *</font>\n<font color=\"#00FF00\">شیر خورده؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FFFF\">\"Alles gut.\"</font>\n<font color=\"#00FF00\">Hast du ihr was zu essen gegeben?</font>",
    "text": "<font color=\"#00FFFF\">«همه‌چی خوبه»</font>\n<font color=\"#00FF00\">بهش چیزی دادی بخوره؟</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#00FFFF\">\"Sie hatte ihr Fläschchen,</font>\n<font color=\"#00FFFF\">danach eine Gurke.</font>",
    "text": "<font color=\"#00FFFF\">«شیرشو خورد،</font>\n<font color=\"#00FFFF\">بعدش هم یه خیار بهش دادم»</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Auweia, Theo. Wann hast du</font>\n<font color=\"#FFFF00\">das letzte Mal geschlafen?</font>",
    "text": "<font color=\"#FFFF00\">ای وای تئو، آخرین بار</font>\n<font color=\"#FFFF00\">کی خوابیدی؟</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#00FFFF\">Warte kurz. Ich unterhalte mich.</font>",
    "text": "<font color=\"#00FFFF\">یه لحظه صبر کن، دارم حرف می‌زنم</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFF00\">Darf ich die Kleine mal halten?</font>\n<font color=\"#FFFF00\">Mensch.</font>",
    "text": "<font color=\"#FFFF00\">می‌شه این کوچولو رو بدم دست من؟</font>\n<font color=\"#FFFF00\">ای بابا</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFF00\">Gott, da muss ich</font>\n<font color=\"#FFFF00\">mich erst mal hinsetzen.</font>",
    "text": "<font color=\"#FFFF00\">خدای من، باید</font>\n<font color=\"#FFFF00\">اول یه جا بشینم</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Tag, Mari.\"</font>\n<font color=\"#00FF00\">Hallo, Andi.</font>",
    "text": "<font color=\"#FFFF00\">سلام ماری»</font>\n<font color=\"#00FF00\">سلام اندی</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#00FF00\">Kannst du meine Tochter</font>\n<font color=\"#00FF00\">wieder Theo kurz geben?</font>",
    "text": "<font color=\"#00FF00\">می‌شه دخترمو</font>\n<font color=\"#00FF00\">یه لحظه دوباره بدی به تئو؟</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFF00\">\"Du, Mari, was ich sagen wollte,</font>\n<font color=\"#FFFF00\">das ist wirklich eine ganz Süße.</font>",
    "text": "<font color=\"#FFFF00\">ماری، می‌خواستم بگم،</font>\n<font color=\"#FFFF00\">این واقعاً خیلی جیگره</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Eine Süße ist das.\"</font>\n<font color=\"#00FF00\">Ja.</font>",
    "text": "<font color=\"#FFFF00\">خیلی نازه</font>\n<font color=\"#00FF00\">آره</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">\"Pass auf, mein Rocco</font>\n<font color=\"#FFFF00\">ist ja jetzt in dem Alter,</font>",
    "text": "<font color=\"#FFFF00\">ببین، روکو پسر من</font>\n<font color=\"#FFFF00\">دیگه به اون سنی رسیده</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">wo er Praktikum machen darf</font>\n<font color=\"#FFFF00\">von der Schule her.</font>",
    "text": "<font color=\"#FFFF00\">که باید از طرف مدرسه</font>\n<font color=\"#FFFF00\">بره کارآموزی</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">Also Schülerpraktikum.</font>",
    "text": "<font color=\"#FFFF00\">یعنی کارآموزی دانش‌آموزی</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFF00\">Da habe ich mich gefragt, ob er es</font>\n<font color=\"#FFFF00\">bei dir in der Firma machen kann,</font>",
    "text": "<font color=\"#FFFF00\">واسه همین گفتم شاید بتونه</font>\n<font color=\"#FFFF00\">بیاد پیش تو تو شرکت کارآموزی کنه</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">wo du arbeitest, bei Tecla,</font>\n<font color=\"#FFFF00\">weißt du?</font>",
    "text": "<font color=\"#FFFF00\">همون‌جا که کار می‌کنی، تکلا،</font>\n<font color=\"#FFFF00\">می‌دونی که؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Bei Tecla, Tecla, Tecla.</font>\n<font color=\"#FFFF00\">Kennst du \"Düsenjäger\", Schnuckel?</font>",
    "text": "<font color=\"#FFFF00\">تکلا، تکلا، تکلا</font>\n<font color=\"#FFFF00\">«جت جنگنده» رو می‌شناسی، عسل؟</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Hui, ui, ui!\"</font>",
    "text": "<font color=\"#FFFF00\">اوووه، ایول</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#00FF00\">Hey, ey. Andi!</font>",
    "text": "<font color=\"#00FF00\">هی، اندی</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#00FF00\">Ist das nicht zu viel für sie?</font>",
    "text": "<font color=\"#00FF00\">این براش خیلی زیاد نیست؟</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">\"Die sind robuster, als man denkt.\"</font>\n<font color=\"#00FF00\">Andi!</font>",
    "text": "<font color=\"#FFFF00\">از اون چیزی که فکر می‌کنی مقاوم‌ترن</font>\n<font color=\"#00FF00\">اندی</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#00FFFF\">\"Das reicht!</font>\n<font color=\"#FFFF00\">Ich habe dich doch.\"</font>",
    "text": "<font color=\"#00FFFF\">کافیه</font>\n<font color=\"#FFFF00\">من که پیشتم</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FF00\">Andi!</font>\n<font color=\"#FFFF00\">\"Ich habe dich doch.\"</font>",
    "text": "<font color=\"#00FF00\">اندی</font>\n<font color=\"#FFFF00\">من که پیشتم</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#00FF00\">Das kriegen wir hin</font>\n<font color=\"#00FF00\">mit dem Praktikum.</font>",
    "text": "<font color=\"#00FF00\">کارآموزی رو ردیف می‌کنیم</font>\n<font color=\"#00FF00\">درستش می‌کنیم</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FFFF\">\"Vorsichtig, das Beet.</font>\n<font color=\"#FFFF00\">Ach, tatsächlich?</font>",
    "text": "<font color=\"#00FFFF\">مواظب باش، باغچه</font>\n<font color=\"#FFFF00\">جدی؟</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Mensch. Das wäre toll, Mari.\"</font>\n<font color=\"#00FF00\">Ja, kannst du Frida Theo geben?</font>",
    "text": "<font color=\"#FFFF00\">ایول، عالی می‌شه ماری</font>\n<font color=\"#00FF00\">آره، می‌تونی فریدا رو بدی به تئو؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">\"Dann kommen wir</font>\n<font color=\"#FFFF00\">morgen einfach vorbei.</font>",
    "text": "<font color=\"#FFFF00\">پس فردا</font>\n<font color=\"#FFFF00\">همین‌طوری یه سر می‌زنیم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">Kommen wir einfach rum.\"</font>\n<font color=\"#00FF00\">Ja, das besprechen wir morgen.</font>",
    "text": "<font color=\"#FFFF00\">یه سر می‌آییم اونجا</font>\n<font color=\"#00FF00\">آره، فردا در موردش حرف می‌زنیم</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">\"Du hast eine tolle Chefin</font>\n<font color=\"#FFFF00\">als Mama. Tschüss, Mari.</font>",
    "text": "<font color=\"#FFFF00\">مامانت یه رئیس فوق‌العاده‌ست</font>\n<font color=\"#FFFF00\">خداحافظ ماری</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFF00\">So.</font>",
    "text": "<font color=\"#FFFF00\">خب</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FFFF\">Danke, Andi.</font>",
    "text": "<font color=\"#00FFFF\">ممنون اندی</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#00FFFF\">Ich habe sie.\"</font>",
    "text": "<font color=\"#00FFFF\">گرفتمش</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FF00FF\">Rocco?</font>",
    "text": "<font color=\"#FF00FF\">روکو؟</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FF00FF\">Papa und ich haben beschlossen,</font>\n<font color=\"#FF00FF\">dass du Verantwortung lernst.</font>",
    "text": "<font color=\"#FF00FF\">من و بابات تصمیم گرفتیم</font>\n<font color=\"#FF00FF\">که یاد بگیری مسئولیت‌پذیر باشی</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FF00FF\">Weißt du, du musst dich mal</font>\n<font color=\"#FF00FF\">selber um deine Sachen kümmern.</font>",
    "text": "<font color=\"#FF00FF\">ببین، باید یاد بگیری</font>\n<font color=\"#FF00FF\">خودت به کارات برسی</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FF00FF\">Hast du verstanden?</font>",
    "text": "<font color=\"#FF00FF\">فهمیدی چی گفتم؟</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FF00FF\">Gut, weil das hier</font>\n<font color=\"#FF00FF\">ist deine Verantwortung.</font>",
    "text": "<font color=\"#FF00FF\">خوبه، چون این موجود</font>\n<font color=\"#FF00FF\">مسئولیتش با توئه</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FF00FF\">Nicht schütteln, das lebt.</font>",
    "text": "<font color=\"#FF00FF\">تکونش نده، زنده‌ست</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FF00FF\">Noch jedenfalls.</font>",
    "text": "<font color=\"#FF00FF\">حداقل فعلاً که هست</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Ist das eine Maus?</font>",
    "text": "<font color=\"#FFFFFF\">این موشه؟</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FF00FF\">Das ist ein gefleckter Goldhamster.</font>",
    "text": "<font color=\"#FF00FF\">این یه همستر طلایی خال‌داره</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FF00FF\">Um den musst du dich gut kümmern.</font>",
    "text": "<font color=\"#FF00FF\">باید خوب ازش مراقبت کنی</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FF00FF\">Füttern, Käfig sauber halten und</font>\n<font color=\"#FF00FF\">vor allem nicht ausbüxen lassen.</font>",
    "text": "<font color=\"#FF00FF\">غذا دادن، تمیز کردن قفس و</font>\n<font color=\"#FF00FF\">مهم‌تر از همه اینکه نذاری در بره</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FF00FF\">Hast du verstanden?</font>",
    "text": "<font color=\"#FF00FF\">فهمیدی؟</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFFFF\">Kann ich nicht lieber</font>\n<font color=\"#FFFFFF\">einen Skorpion haben?</font>",
    "text": "<font color=\"#FFFFFF\">نمیشه به جاش</font>\n<font color=\"#FFFFFF\">یه عقرب داشته باشم؟</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FF00FF\">Nein.</font>",
    "text": "<font color=\"#FF00FF\">نه</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">* Die Tür knallt. *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای کوبیده شدن در *</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">* Zoe lacht. *</font>",
    "text": "<font color=\"#FFFFFF\">* خنده زوئی *</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Johnny!</font>",
    "text": "<font color=\"#FFFFFF\">جانی!</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFFFF\">Johnny!</font>",
    "text": "<font color=\"#FFFFFF\">جانی!</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FF00\">Äh...</font>",
    "text": "<font color=\"#00FF00\">اِ...</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FF00\">Gute Nacht.</font>\n<font color=\"#FFFFFF\">Gute Nacht.</font>",
    "text": "<font color=\"#00FF00\">شب بخیر</font>\n<font color=\"#FFFFFF\">شب بخیر</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">* Gefühlvolle Musik *</font>",
    "text": "<font color=\"#FFFFFF\">* موسیقی احساسی *</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FF00FF\">Besetzt.</font>\n<font color=\"#FFFF00\">Oh, Entschuldigung.</font>",
    "text": "<font color=\"#FF00FF\">اشغاله</font>\n<font color=\"#FFFF00\">اوه، ببخشید</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFF00\">Aber nicht wieder</font>\n<font color=\"#FFFF00\">eine von deinen Sitzungen.</font>",
    "text": "<font color=\"#FFFF00\">ولی باز دوباره</font>\n<font color=\"#FFFF00\">شروع نکن به اون جلساتت</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FF00FF\">Mann, Motte.</font>\n<font color=\"#FFFFFF\">* Quietschen *</font>",
    "text": "<font color=\"#FF00FF\">ای بابا، موته</font>\n<font color=\"#FFFFFF\">* صدای جیغ *</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFF00\">Uh.</font>\n<font color=\"#FF00FF\">Ah!</font>",
    "text": "<font color=\"#FFFF00\">اوه</font>\n<font color=\"#FF00FF\">آخ!</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Was ist denn das?</font>\n<font color=\"#FF00FF\">Roccos Hamster, du Trampel.</font>",
    "text": "<font color=\"#FFFF00\">این دیگه چیه؟</font>\n<font color=\"#FF00FF\">همستر روکیه، دست‌پاچلفتی</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Seit wann hat der einen Hamster?</font>\n<font color=\"#FFFFFF\">Alles okay?</font>",
    "text": "<font color=\"#FFFF00\">از کی تا حالا اون همستر داره؟</font>\n<font color=\"#FFFFFF\">همه چی روبه‌راهه؟</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFF00\">Ja, alles okay, Rocci.</font>\n<font color=\"#FFFF00\">Kannst wieder in dein Zimmer.</font>",
    "text": "<font color=\"#FFFF00\">آره، همه‌چی مرتبه روکی</font>\n<font color=\"#FFFF00\">می‌تونی برگردی تو اتاقت</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Falscher Alarm.</font>\n<font color=\"#FFFFFF\">Warum hat Mama geschrien?</font>",
    "text": "<font color=\"#FFFF00\">الکی بود، چیزی نبود</font>\n<font color=\"#FFFFFF\">چرا مامان جیغ زد؟</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">Die hat geschrien, weil ...</font>",
    "text": "<font color=\"#FFFF00\">جیغ زد چون...</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFF00\">du ein verwöhnter Bengel bist, der</font>\n<font color=\"#FFFF00\">auf seine Sachen aufpassen soll.</font>",
    "text": "<font color=\"#FFFF00\">یه بچه لوس و ننری که</font>\n<font color=\"#FFFF00\">باید یاد بگیره از وسایلش مراقبت کنه</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Was ist da?</font>\n<font color=\"#FF00FF\">Da ist nichts, Rocco.</font>",
    "text": "<font color=\"#FFFFFF\">اونجا چیه؟</font>\n<font color=\"#FF00FF\">چیزی نیست روکو</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FF00FF\">Geh wieder in dein Zimmer.</font>",
    "text": "<font color=\"#FF00FF\">برگرد برو تو اتاقت</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Ist das Flecki?</font>",
    "text": "<font color=\"#FFFFFF\">اون فلکیه؟</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Komm, Junge, kein schöner Anblick.</font>\n<font color=\"#FF00FF\">Flecki geht's gut.</font>",
    "text": "<font color=\"#FFFF00\">بیا پسر، صحنه قشنگی نیست</font>\n<font color=\"#FF00FF\">حال فلکی خوبه</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Aber der ist in zwei Hälften.</font>",
    "text": "<font color=\"#FFFFFF\">ولی اون دو نصف شده</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FF00FF\">Ich habe gesagt,</font>\n<font color=\"#FF00FF\">dass alles okay ist.</font>",
    "text": "<font color=\"#FF00FF\">بهت گفتم که</font>\n<font color=\"#FF00FF\">همه‌چی مرتبه</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FF00FF\">Der muss nur operiert werden,</font>\n<font color=\"#FF00FF\">dann geht's dem wieder gut.</font>",
    "text": "<font color=\"#FF00FF\">فقط باید عمل بشه</font>\n<font color=\"#FF00FF\">بعدش دوباره حالش خوب می‌شه</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FF00FF\">Hm?</font>",
    "text": "<font color=\"#FF00FF\">هوم؟</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFFFF\">* Jemand weint. *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای گریه کسی *</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFFFF\">Ich bin sicher, es warten noch</font>\n<font color=\"#FFFFFF\">viele Herausforderungen auf Sie.</font>",
    "text": "<font color=\"#FFFFFF\">مطمئنم که هنوز چالش‌های زیادی</font>\n<font color=\"#FFFFFF\">در انتظار شماست</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFFFF\">Das Leben ist zu kurz,</font>\n<font color=\"#FFFFFF\">um traurig zu sein.</font>",
    "text": "<font color=\"#FFFFFF\">زندگی خیلی کوتاه‌تر از اونه</font>\n<font color=\"#FFFFFF\">که بخوایم غمگین باشیم</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FF00\">Klaus-Jürgen.</font>",
    "text": "<font color=\"#00FF00\">کلاوس-یورگن</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFFFF\">Viel Glück.</font>",
    "text": "<font color=\"#FFFFFF\">موفق باشی</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FF00\">Das ist so hart.</font>",
    "text": "<font color=\"#00FF00\">خیلی سخته</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFFFF\">Ja.</font>",
    "text": "<font color=\"#FFFFFF\">آره</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFFFF\">Aber notwendig, Mari.</font>",
    "text": "<font color=\"#FFFFFF\">ولی لازمه، ماری</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Wir müssen hinschauen,</font>\n<font color=\"#FFFFFF\">wo das Potenzial liegt.</font>",
    "text": "<font color=\"#FFFFFF\">باید دقیق نگاه کنیم</font>\n<font color=\"#FFFFFF\">که پتانسیل کجا نهفته‌ست</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#FFFFFF\">Ingenieure können wir nicht feuern,</font>\n<font color=\"#FFFFFF\">die brauchen wir,</font>",
    "text": "<font color=\"#FFFFFF\">مهندس‌ها رو که نمی‌تونیم اخراج کنیم،</font>\n<font color=\"#FFFFFF\">بهشون نیاز داریم</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">aber die sind nicht divers.</font>",
    "text": "<font color=\"#FFFFFF\">ولی اونا متنوع نیستن</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFFFF\">Diverse können wir nicht feuern,</font>\n<font color=\"#FFFFFF\">weil die sind divers.</font>",
    "text": "<font color=\"#FFFFFF\">آدم‌های متنوع رو هم نمی‌تونیم اخراج کنیم،</font>\n<font color=\"#FFFFFF\">چون اونا متنوع هستن</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">Das Kätzchen</font>\n<font color=\"#FFFFFF\">beißt sich in den Schwanz.</font>",
    "text": "<font color=\"#FFFFFF\">این یه دور باطله</font>\n<font color=\"#FFFFFF\">که هیچ‌وقت تموم نمی‌شه</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Dann muss der liebe Klaus-Jürgen</font>\n<font color=\"#FFFFFF\">vom Sales-Team daran glauben.</font>",
    "text": "<font color=\"#FFFFFF\">اون‌وقت اون کلاوس-یورگنِ بیچاره</font>\n<font color=\"#FFFFFF\">از تیم فروش باید قربانی بشه</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#00FF00\">Klaus-Jürgen hat drei Kinder.</font>",
    "text": "<font color=\"#00FF00\">کلاوس-یورگن سه تا بچه داره</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Es ist vertrackt.</font>\n<font color=\"#FFFFFF\">* Klopfen *</font>",
    "text": "<font color=\"#FFFFFF\">اوضاع خیلی پیچیده شده</font>\n<font color=\"#FFFFFF\">* صدای در زدن *</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Aus welcher Abteilung ist der?</font>",
    "text": "<font color=\"#FFFFFF\">اون از کدوم بخش اومده؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#00FF00\">Construction Facilities, Rezeption.</font>",
    "text": "<font color=\"#00FF00\">بخش تاسیسات، پذیرش</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#00FF00\">Entschuldigen Sie, Frau Sawadi,</font>",
    "text": "<font color=\"#00FF00\">ببخشید خانم ساوادی</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#00FF00\">in der Lobby wartet ein Herr Knuppe</font>\n<font color=\"#00FF00\">auf Sie mit seinem Sohn.</font>",
    "text": "<font color=\"#00FF00\">یه آقای کنوپه تو لابی منتظرتونه</font>\n<font color=\"#00FF00\">به همراه پسرش</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Du bist engagiert, zielorientiert,</font>\n<font color=\"#FFFF00\">eine hohe Auffassungsgabe hast du.</font>",
    "text": "<font color=\"#FFFF00\">تو خیلی فعالی، هدف‌داری</font>\n<font color=\"#FFFF00\">و خیلی هم زود همه چی رو می‌گیری</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Das sagst du denen,</font>\n<font color=\"#FFFF00\">wenn sie fragen.</font>",
    "text": "<font color=\"#FFFF00\">اگه ازت پرسیدن، اینا رو بهشون بگو</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Fragen stellen, damit die denken,</font>\n<font color=\"#FFFF00\">du bist interessiert.</font>",
    "text": "<font color=\"#FFFF00\">سوال بپرس تا فکر کنن</font>\n<font color=\"#FFFF00\">که خیلی مشتاقی</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">Aber nicht zu oft,</font>\n<font color=\"#FFFF00\">sonst denken die, du bist blöd.</font>",
    "text": "<font color=\"#FFFF00\">ولی نه خیلی زیاد</font>\n<font color=\"#FFFF00\">وگرنه فکر می‌کنن خنگی</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">Tja.</font>",
    "text": "<font color=\"#FFFF00\">خب دیگه</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Mensch, Mari.</font>",
    "text": "<font color=\"#FFFF00\">ای بابا، ماری</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFF00\">Das ist ja...</font>",
    "text": "<font color=\"#FFFF00\">این واقعاً...</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Also Donnerwetter, du.</font>\n<font color=\"#FFFF00\">Ja, das ist...</font>",
    "text": "<font color=\"#FFFF00\">دمت گرم واقعاً</font>\n<font color=\"#FFFF00\">آره، این...</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">Jetzt verstehe ich, warum du</font>\n<font color=\"#FFFF00\">ein Angeber bist, wäre ich auch.</font>",
    "text": "<font color=\"#FFFF00\">حالا می‌فهمم چرا اینقدر پز می‌دی</font>\n<font color=\"#FFFF00\">منم بودم پز می‌دادم</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FF00\">Wir haben uns missverstanden. Ich</font>\n<font color=\"#00FF00\">meinte, dass wir vorher sprechen.</font>",
    "text": "<font color=\"#00FF00\">فکر کنم سوءتفاهم شده، منظورم این بود</font>\n<font color=\"#00FF00\">که قبلش با هم حرف بزنیم</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFF00\">Du, gar kein Thema.</font>\n<font color=\"#FFFF00\">Ich wollte Danke sagen.</font>",
    "text": "<font color=\"#FFFF00\">نه بابا، این حرفا چیه</font>\n<font color=\"#FFFF00\">فقط می‌خواستم تشکر کنم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">Dass du das gedeichselt hast</font>\n<font color=\"#FFFF00\">für den Lümmel.</font>",
    "text": "<font color=\"#FFFF00\">که این کار رو واسه این وروجک</font>\n<font color=\"#FFFF00\">ردیف کردی</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Er freut sich schon</font>\n<font color=\"#FFFF00\">aufs Bewerbungsgespräch.</font>",
    "text": "<font color=\"#FFFF00\">خیلی ذوق داره واسه</font>\n<font color=\"#FFFF00\">جلسه مصاحبه‌ش</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">Ja.</font>",
    "text": "<font color=\"#FFFFFF\">آره</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FF00\">Wann willst du bei uns anfangen?</font>",
    "text": "<font color=\"#00FF00\">کی می‌خوای کار رو شروع کنی؟</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#FFFFFF\">Weiß nicht.</font>\n<font color=\"#FFFF00\">Na ja, sagen wir mal so...</font>",
    "text": "<font color=\"#FFFFFF\">نمی‌دونم</font>\n<font color=\"#FFFF00\">خب، بذار این‌طوری بگم...</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#FFFF00\">Die Praktikumswochen</font>\n<font color=\"#FFFF00\">laufen seit gestern.</font>",
    "text": "<font color=\"#FFFF00\">دوره کارآموزی</font>\n<font color=\"#FFFF00\">از دیروز شروع شده</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFFFF\">* Stummer Dialog *</font>",
    "text": "<font color=\"#FFFFFF\">* گفتگوی بی‌کلام *</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">* Das Baby schreit. *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای گریه بچه *</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFF00\">Mensch,</font>\n<font color=\"#FFFF00\">du siehst ja aus wie ausgekotzt.</font>",
    "text": "<font color=\"#FFFF00\">پسر،</font>\n<font color=\"#FFFF00\">چرا این شکلی شدی، انگار از دهن گربه دراومدی</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFF00\">Die Kleine hält dich auf Trab.</font>\n<font color=\"#00FFFF\">Nee, geht schon.</font>",
    "text": "<font color=\"#FFFF00\">این کوچولو حسابی خسته‌ت کرده</font>\n<font color=\"#00FFFF\">نه، خوبم</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#00FFFF\">Ist nur quengelig.</font>\n<font color=\"#FFFF00\">Was hast sie denn?</font>",
    "text": "<font color=\"#00FFFF\">فقط یکم بی‌قراره</font>\n<font color=\"#FFFF00\">چشه مگه؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFF00\">Kann ich sie mal sehen?</font>\n<font color=\"#00FFFF\">Die braucht grad eher ...</font>",
    "text": "<font color=\"#FFFF00\">می‌تونم ببینمش؟</font>\n<font color=\"#00FFFF\">الان بیشتر نیاز داره به...</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFF00\">Mein Hase, jetzt gucken wir mal.</font>\n<font color=\"#00FFFF\">... Ruhe.</font>",
    "text": "<font color=\"#FFFF00\">خرگوش کوچولوی من، بذار ببینم چشه</font>\n<font color=\"#00FFFF\">... آرامش</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Sie quengelt, weil sie Hunger hat</font>\n<font color=\"#FFFF00\">oder der Stuhl drückt.</font>",
    "text": "<font color=\"#FFFF00\">به خاطر گرسنگی بی‌قراری می‌کنه</font>\n<font color=\"#FFFF00\">یا شاید هم دل‌پیچه داره</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Geht immer nur</font>\n<font color=\"#FFFF00\">ums Essen oder Kacken.</font>",
    "text": "<font color=\"#FFFF00\">همه‌ش یا بحث خوردنه</font>\n<font color=\"#FFFF00\">یا بحث پی‌پی کردن</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Erst Essen, dann Kacka. Weißt du?</font>\n<font color=\"#FFFF00\">Erst Essen, dann Kacka.</font>",
    "text": "<font color=\"#FFFF00\">اول غذا، بعد پی‌پی، می‌فهمی؟</font>\n<font color=\"#FFFF00\">اول غذا، بعد پی‌پی</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FFFF00\">Erst Essen, dann Kacka.</font>\n<font color=\"#FFFF00\">Erst Essen, dann Kacka.</font>",
    "text": "<font color=\"#FFFF00\">اول غذا، بعد پی‌پی</font>\n<font color=\"#FFFF00\">اول غذا، بعد پی‌پی</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#00FFFF\">Sie macht aber kein Kacka mehr.</font>",
    "text": "<font color=\"#00FFFF\">ولی دیگه پی‌پی نمی‌کنه</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">Seit wann schon nicht?</font>",
    "text": "<font color=\"#FFFF00\">از کی تا حالا؟</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#00FFFF\">Seit sieben Tagen.</font>\n<font color=\"#FFFF00\">Oh.</font>",
    "text": "<font color=\"#00FFFF\">هفت روزه</font>\n<font color=\"#FFFF00\">اوه</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#00FFFF\">Ich kriege das alles nicht hin,</font>\n<font color=\"#00FFFF\">Andi.</font>",
    "text": "<font color=\"#00FFFF\">من از پسِ هیچ‌کدوم برنمیام،</font>\n<font color=\"#00FFFF\">اندی</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#00FFFF\">Nicht so,</font>\n<font color=\"#00FFFF\">wie ich es mir vorgestellt habe.</font>",
    "text": "<font color=\"#00FFFF\">اون‌طوری که فکر می‌کردم</font>\n<font color=\"#00FFFF\">پیش نمیره</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#00FFFF\">Ich habe jedes Buch gelesen</font>",
    "text": "<font color=\"#00FFFF\">من تمام کتاب‌ها رو خوندم</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#00FFFF\">und alle Video geschaut,</font>\n<font color=\"#00FFFF\">die man über Babys finden kann.</font>",
    "text": "<font color=\"#00FFFF\">و هر چی ویدیو درباره بچه‌ها بود</font>\n<font color=\"#00FFFF\">دیدم</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#00FFFF\">Sorry. Sorry, Andi.</font>\n<font color=\"#00FFFF\">Ich weiß nicht, wo das herkam.</font>",
    "text": "<font color=\"#00FFFF\">ببخشید. ببخشید اندی</font>\n<font color=\"#00FFFF\">نمی‌دونم چرا این‌طوری شدم</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#00FFFF\">Entschuldige.</font>\n<font color=\"#FFFF00\">Schon gut, kriegen wir hin.</font>",
    "text": "<font color=\"#00FFFF\">عذر می‌خوام</font>\n<font color=\"#FFFF00\">بی‌خیال، درستش می‌کنیم</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FFFF00\">Habt ihr Kartoffelbrei</font>\n<font color=\"#FFFF00\">aus der Tüte?</font>",
    "text": "<font color=\"#FFFF00\">پوره سیب‌زمینی آماده</font>\n<font color=\"#FFFF00\">توی خونه دارید؟</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#00FFFF\">Nein.</font>",
    "text": "<font color=\"#00FFFF\">نه</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FFFF\">Andi?</font>\n<font color=\"#FFFF00\">Ja, Theo?</font>",
    "text": "<font color=\"#00FFFF\">اندی؟</font>\n<font color=\"#FFFF00\">بله تئو؟</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#00FFFF\">Stört es dich,</font>\n<font color=\"#00FFFF\">wenn ich kurz die Augen zumache?</font>",
    "text": "<font color=\"#00FFFF\">مشکلی نداری</font>\n<font color=\"#00FFFF\">اگه یه لحظه چشمام رو ببندم؟</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#00FFFF\">Nur ganz kurz.</font>\n<font color=\"#FFFF00\">Nö, Quatsch.</font>",
    "text": "<font color=\"#00FFFF\">فقط یه لحظه کوتاه</font>\n<font color=\"#FFFF00\">نه، چه حرفیه</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#FFFF00\">Mach es dir gemütlich.</font>\n<font color=\"#FFFF00\">Fühl dich wie zu Hause.</font>",
    "text": "<font color=\"#FFFF00\">راحت باش</font>\n<font color=\"#FFFF00\">خونه خودته، تعارف نکن</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Aber vielleicht</font>\n<font color=\"#FFFFFF\">will er gar nicht im Käfig sein.</font>",
    "text": "<font color=\"#FFFFFF\">ولی شاید</font>\n<font color=\"#FFFFFF\">اصلاً دلش نمی‌خواد تو قفس باشه</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FF00FF\">Wir alle müssen Sachen machen,</font>\n<font color=\"#FF00FF\">auf die wir keinen Bock haben.</font>",
    "text": "<font color=\"#FF00FF\">همه‌مون مجبوریم یه کارایی بکنیم</font>\n<font color=\"#FF00FF\">که اصلاً دلمون نمی‌خواد</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FF00FF\">Weil wir</font>\n<font color=\"#FF00FF\">verantwortungsvolle Menschen sind,</font>",
    "text": "<font color=\"#FF00FF\">چون ما آدم‌های</font>\n<font color=\"#FF00FF\">مسئولیت‌پذیری هستیم</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FF00FF\">machen wir das trotzdem,</font>\n<font color=\"#FF00FF\">verstanden?</font>",
    "text": "<font color=\"#FF00FF\">با این حال انجامش می‌دیم</font>\n<font color=\"#FF00FF\">فهمیدی؟</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FF00FF\">Gut.</font>",
    "text": "<font color=\"#FF00FF\">خوبه</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Mach's gut, Flecki.</font>\n<font color=\"#FFFFFF\">* Poltern *</font>",
    "text": "<font color=\"#FFFFFF\">خداحافظ فلکی</font>\n<font color=\"#FFFFFF\">* صدای تق‌وتوق *</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFF00\">Ah,</font>\n<font color=\"#FFFF00\">das war so ein schöner Tag heute.</font>",
    "text": "<font color=\"#FFFF00\">آخ</font>\n<font color=\"#FFFF00\">امروز چه روز قشنگی بود</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFF00\">Wo bist du denn?</font>",
    "text": "<font color=\"#FFFF00\">کجایی پس؟</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFF00\">Hallo.</font>",
    "text": "<font color=\"#FFFF00\">سلام</font>"
  },
  {
    "id": 10,
    "source": "<font color=\"#FF00FF\">Was denn?</font>\n<font color=\"#FFFF00\">Na ja, also...</font>",
    "text": "<font color=\"#FF00FF\">چی شده؟</font>\n<font color=\"#FFFF00\">خب، راستش...</font>"
  },
  {
    "id": 11,
    "source": "<font color=\"#FFFF00\">Ich... Ich habe mir gedacht...</font>\n<font color=\"#FF00FF\">Jetzt sag schon.</font>",
    "text": "<font color=\"#FFFF00\">من... با خودم فکر کردم...</font>\n<font color=\"#FF00FF\">خب بگو دیگه</font>"
  },
  {
    "id": 12,
    "source": "<font color=\"#FFFF00\">Mäuschen, lass mich mal</font>\n<font color=\"#FFFF00\">ein bisschen romantisch sein.</font>",
    "text": "<font color=\"#FFFF00\">عزیزم، بذار یه ذره</font>\n<font color=\"#FFFF00\">رمانتیک باشم</font>"
  },
  {
    "id": 13,
    "source": "<font color=\"#FFFF00\">Weißt du, ich habe mich gefragt ...</font>",
    "text": "<font color=\"#FFFF00\">می‌دونی، از خودم پرسیدم...</font>"
  },
  {
    "id": 14,
    "source": "<font color=\"#FFFF00\">was dagegenspricht, dass wir</font>\n<font color=\"#FFFF00\">auch noch mal ein Baby haben.</font>",
    "text": "<font color=\"#FFFF00\">چه اشکالی داره که ما</font>\n<font color=\"#FFFF00\">دوباره بچه‌دار بشیم</font>"
  },
  {
    "id": 15,
    "source": "<font color=\"#FFFF00\">Ein Schwesterchen für Rocci,</font>\n<font color=\"#FFFF00\">das würde ihm auch guttun.</font>",
    "text": "<font color=\"#FFFF00\">یه خواهر کوچولو برای روکی</font>\n<font color=\"#FFFF00\">خیلی هم براش خوبه</font>"
  },
  {
    "id": 16,
    "source": "<font color=\"#FFFF00\">Als großer Bruder lernst du</font>\n<font color=\"#FFFF00\">so richtig Verantwortung.</font>",
    "text": "<font color=\"#FFFF00\">به عنوان داداش بزرگتر</font>\n<font color=\"#FFFF00\">قشنگ مسئولیت‌پذیری رو یاد می‌گیری</font>"
  },
  {
    "id": 17,
    "source": "<font color=\"#FFFF00\">Sag mal, hast du noch Socken an?</font>\n<font color=\"#FF00FF\">Hä?</font>",
    "text": "<font color=\"#FFFF00\">بگو ببینم، هنوز جوراب پاته؟</font>\n<font color=\"#FF00FF\">ها؟</font>"
  },
  {
    "id": 18,
    "source": "<font color=\"#FFFFFF\">* Quietschen *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای جیغ *</font>"
  },
  {
    "id": 19,
    "source": "<font color=\"#FFFF00\">I!</font>",
    "text": "<font color=\"#FFFF00\">ای!</font>"
  },
  {
    "id": 20,
    "source": "<font color=\"#FF00FF\">Motte!</font>",
    "text": "<font color=\"#FF00FF\">موته!</font>"
  },
  {
    "id": 21,
    "source": "<font color=\"#FFFFFF\">* Hämmern *</font>",
    "text": "<font color=\"#FFFFFF\">* صدای چکش *</font>"
  },
  {
    "id": 22,
    "source": "<font color=\"#00FF00\">Das kann doch nicht wahr sein.</font>",
    "text": "<font color=\"#00FF00\">این دیگه غیرممکنه</font>"
  },
  {
    "id": 23,
    "source": "<font color=\"#00FF00\">Scheiße!</font>",
    "text": "<font color=\"#00FF00\">لعنتی!</font>"
  },
  {
    "id": 24,
    "source": "<font color=\"#00FF00\">Oh sorry, Rocco.</font>\n<font color=\"#FFFFFF\">Ist okay, Mama sagt das auch immer.</font>",
    "text": "<font color=\"#00FF00\">اوه ببخشید روکو</font>\n<font color=\"#FFFFFF\">اشکالی نداره، مامانم همیشه همینو می‌گه</font>"
  },
  {
    "id": 25,
    "source": "<font color=\"#00FF00\">Ich sage das,</font>\n<font color=\"#00FF00\">weil mein Computer abgestürzt ist.</font>",
    "text": "<font color=\"#00FF00\">من اینو می‌گم</font>\n<font color=\"#00FF00\">چون کامپیوترم هنگ کرده</font>"
  }
]

[
  {
    "id": 1,
    "source": "<font color=\"#FFFFFF\">Hm?</font>\n<font color=\"#00FF00\">Danke.</font>",
    "text": "<font color=\"#FFFFFF\">ها؟</font>\n<font color=\"#00FF00\">ممنون</font>"
  },
  {
    "id": 2,
    "source": "<font color=\"#FFFFFF\">Hm?</font>\n<font color=\"#FFFFFF\">- Nein.</font>",
    "text": "<font color=\"#FFFFFF\">ها؟</font>\n<font color=\"#FFFFFF\">- نه</font>"
  },
  {
    "id": 3,
    "source": "<font color=\"#FFFFFF\">Mmh.</font>",
    "text": "<font color=\"#FFFFFF\">اوم</font>"
  },
  {
    "id": 4,
    "source": "<font color=\"#FFFFFF\">Hallo, Rocco, und willkommen</font>\n<font color=\"#FFFFFF\">beim Tecla-Team Germany.</font>",
    "text": "<font color=\"#FFFFFF\">سلام روکو، به تیم تکلا آلمان</font>\n<font color=\"#FFFFFF\">خوش اومدی</font>"
  },
  {
    "id": 5,
    "source": "<font color=\"#FFFFFF\">Wie ich gehört habe, hat dir</font>\n<font color=\"#FFFFFF\">der erste Tag bei uns gut gefallen.</font>",
    "text": "<font color=\"#FFFFFF\">شنیدم که روز اول کاریت</font>\n<font color=\"#FFFFFF\">پیش ما خیلی خوب بوده</font>"
  },
  {
    "id": 6,
    "source": "<font color=\"#FFFFFF\">Das ist großartig,</font>\n<font color=\"#FFFFFF\">das ist wunderbar.</font>",
    "text": "<font color=\"#FFFFFF\">این عالیه،</font>\n<font color=\"#FFFFFF\">فوق‌العاده‌ست</font>"
  },
  {
    "id": 7,
    "source": "<font color=\"#FFFFFF\">Erzähl uns ein bisschen davon.</font>",
    "text": "<font color=\"#FFFFFF\">یه کم برامون ازش تعریف کن</font>"
  },
  {
    "id": 8,
    "source": "<font color=\"#FFFFFF\">Mir hat mein erster Tag bei uns</font>\n<font color=\"#FFFFFF\">so richtig gut gefallen.</font>",
    "text": "<font color=\"#FFFFFF\">روز اول کاریم پیش شما</font>\n<font color=\"#FFFFFF\">واقعاً خیلی بهم چسبید</font>"
  },
  {
    "id": 9,
    "source": "<font color=\"#FFFFFF\">Okay, das war schon mal gut.</font>\n<font color=\"#FFFFFF\">Danke für das wertvolle Feedback.</font>",
